package com.lcsalvess.bankingsystem.testsupport;

import com.lcsalvess.bankingsystem.entity.address.Address;
import com.lcsalvess.bankingsystem.entity.address.State;
import com.lcsalvess.bankingsystem.entity.client.Client;
import java.util.Locale;
import java.util.Objects;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicLong;
import java.util.regex.Pattern;
import org.springframework.test.util.ReflectionTestUtils;

public final class ClientTestFactory {

  /**
   * Number of clients generated by this factory in the current JVM.
   */
  private static final AtomicLong SEQUENCE = new AtomicLong();

  /**
   * Number of possible 9-digit CPF bases (10^9), including invalid repeated-digit sequences.
   */
  private static final long CPF_BASE_SPACE = 1_000_000_000L;

  /**
   * Number of valid 9-digit CPF bases after excluding the 10 repeated-digit sequences
   * (000000000, 111111111, ..., 999999999).
   */
  private static final long VALID_CPF_BASE_SPACE = CPF_BASE_SPACE - 10;

  /**
   * Randomized token generated once per JVM run to reduce the likelihood of collisions
   * with parallel or repeated runs against a shared database.
   */
  private static final String RUN_TOKEN = createRunToken();

  /**
   * Randomized CPF generation seed shared by all clients created during the JVM run.
   */
  private static final long CPF_RUN_TOKEN =
      Math.floorMod(UUID.randomUUID().getMostSignificantBits(),
          VALID_CPF_BASE_SPACE);

  /**
   * Lowercase alphanumeric words separated by hyphens.
   */
  private static final Pattern LABEL_PATTERN =
      Pattern.compile("[a-z0-9]+(-[a-z0-9]+)*");

  private ClientTestFactory() {
  }

  public static Builder clientBuilder() {
    return clientBuilder("client");
  }

  /**
   * Creates a client builder using the specified label.
   *
   * <p>The label prefixes generated e-mail addresses, making test data traceable
   * to the test that created it (e.g. "account-client", "spec-client").
   *
   * @param label lowercase alphanumeric words separated by hyphens
   * @return a builder configured with the specified label
   * @throws IllegalArgumentException if the label does not match the required format
   */
  public static Builder clientBuilder(String label) {
    if (label == null || !LABEL_PATTERN.matcher(label).matches()) {
      throw new IllegalArgumentException(
          "Label must use lowercase kebab-case."
      );
    }

    return new Builder(label);
  }

  public static final class Builder {

    private final String label;

    private String name = "Jane Doe";
    private String cpf;
    private String email;
    private String phoneNumber = "11999999999";
    private Address address;
    private Long id;

    private Builder(String label) {
      this.label = label;
    }

    public Builder withId(long id) {
      this.id = id;
      return this;
    }

    public Builder withName(String name) {
      this.name = Objects.requireNonNull(name, "Name must not be null.");
      return this;
    }

    public Builder withCpf(String cpf) {
      this.cpf = Objects.requireNonNull(cpf, "CPF must not be null.");
      return this;
    }

    public Builder withEmail(String email) {
      this.email = Objects.requireNonNull(email, "Email must not be null.");
      return this;
    }

    public Builder withPhoneNumber(String phoneNumber) {
      this.phoneNumber = Objects.requireNonNull(
          phoneNumber,
          "Phone number must not be null."
      );
      return this;
    }

    public Builder withAddress(Address address) {
      this.address = Objects.requireNonNull(
          address,
          "Address must not be null."
      );
      return this;
    }

    /**
     * Builds a new client using the configured values.
     *
     * <p>CPF and e-mail are generated when no explicit values are provided.
     * Each invocation consumes a new sequence value, even when some fields
     * are explicitly configured, ensuring that reusing a builder does not
     * generate duplicate default values.
     *
     * @return a new client instance
     */
    public Client build() {
      long sequence = SEQUENCE.getAndIncrement();

      String clientCpf = cpf != null ? cpf : generateCpf(sequence);
      String clientEmail = email != null ? email : generateEmail(label, sequence);
      Address clientAddress = address != null ? address : defaultAddress();

      Client client = new Client(
          name,
          clientCpf,
          clientEmail,
          phoneNumber,
          clientAddress
      );

      if (id != null) {
        ReflectionTestUtils.setField(client, "id", id);
      }

      return client;
    }
  }

  /**
   * Generates a unique test e-mail address.
   *
   * <p>The {@code example.com} domain is reserved for documentation and testing
   * purposes under RFC 2606, preventing generated addresses from targeting
   * real mail domains.
   *
   * @param label    test identifier used to prefix the e-mail address
   * @param sequence unique client sequence within the JVM run
   * @return generated e-mail address
   */
  private static String generateEmail(String label, long sequence) {
    return "%s-%s-%s@example.com".formatted(
        label,
        RUN_TOKEN,
        Long.toString(sequence, 36)
    );
  }

  /**
   * Generates a CPF with valid check digits using the JVM-specific seed
   * and the client sequence.
   *
   * @param sequence unique client sequence within the JVM run
   * @return generated 11-digit CPF
   */
  private static String generateCpf(long sequence) {
    long candidate = Math.floorMod(
        CPF_RUN_TOKEN + sequence,
        VALID_CPF_BASE_SPACE
    );

    long cpfBase = skipRepeatedDigitBases(candidate);

    String base = String.format(Locale.ROOT, "%09d", cpfBase);

    int firstDigit = calculateCpfDigit(base, 9);
    String firstTenDigits = base + firstDigit;

    int secondDigit = calculateCpfDigit(firstTenDigits, 10);

    return firstTenDigits + secondDigit;
  }

  /**
   * Maps a candidate in {@code [0, VALID_CPF_BASE_SPACE)} to a 9-digit base
   * while skipping repeated-digit sequences in ascending order.
   *
   * @param candidate zero-based candidate within the valid CPF base space
   * @return adjusted 9-digit CPF base that does not contain repeated digits
   */
  private static long skipRepeatedDigitBases(long candidate) {
    long adjusted = candidate;

    for (int digit = 0; digit <= 9; digit++) {
      long repeatedBase = digit * 111_111_111L;

      if (adjusted >= repeatedBase) {
        adjusted++;
      }
    }

    return adjusted;
  }

  /**
   * Calculates a CPF check digit using the standard weighted modulo 11 algorithm.
   *
   * @param cpf    existing CPF digits used in the calculation
   * @param length number of existing digits
   * @return calculated check digit
   */
  private static int calculateCpfDigit(String cpf, int length) {
    int sum = 0;

    for (int index = 0; index < length; index++) {
      sum += Character.getNumericValue(cpf.charAt(index))
          * (length + 1 - index);
    }

    int remainder = sum % 11;

    return remainder < 2 ? 0 : 11 - remainder;
  }

  /**
   * Creates the default address used by generated clients.
   *
   * <p>The address corresponds to the MASP location on Avenida Paulista,
   * São Paulo.
   *
   * @return a new address instance
   */
  private static Address defaultAddress() {
    return new Address(
        "Avenida Paulista",
        "1578",
        null,
        "Bela Vista",
        "São Paulo",
        State.SP,
        "01310200"
    );
  }

  /**
   * Generates a randomized 6-character base-36 token.
   *
   * <p>The token distinguishes JVM runs and reduces the likelihood of
   * collisions when tests share a database.
   *
   * @return zero-padded 6-character base-36 token
   */
  private static String createRunToken() {
    long token = Math.floorMod(
        UUID.randomUUID().getMostSignificantBits(),
        36L * 36 * 36 * 36 * 36 * 36
    );

    return String.format(Locale.ROOT, "%6s", Long.toString(token, 36))
        .replace(' ', '0');
  }
}
